  /** Idoneità al loglio (AGFF-Merkblatt 8, sezione 2) */
  function raigrasHinweis(a) {
    const h = a.kopf.hoehe; const s = a.standort; const t = [];
    if (h != null) {
      if (h <= 700) t.push('Altitudine ' + h + ' m: adatta al loglio anche in situazioni rigide (fino a 700 m).');
      else if (h <= 900) t.push('Altitudine ' + h + ' m: adatta solo in situazioni miti (fino a 900 m); in situazioni rigide solo fino a 700 m.');
      else if (h <= 1000) t.push('Altitudine ' + h + ' m: solo loglio inglese e solo in situazioni miti (fino a 1000 m).');
      else t.push('Altitudine ' + h + ' m: oltre 1000 m non adatta al loglio.');
    }
    if (s.wasser === 'trocken' || s.wasser === 'nass') t.push('Regime idrico «' + (s.wasser === 'trocken' ? 'secco' : 'bagnato') + '»: adatti sono i suoli normalmente permeabili con 900–1200 mm di precipitazioni.');
    if (s.boden === 'leicht, sandig' || s.boden === 'schwer, tonig') t.push('Il loglio richiede suoli medi con strato superiore grumoso, senza compattamenti.');
    if (s.naehrstoff === 'mager') t.push('Il loglio richiede P e K «medi» fino a «sufficienti» e regolari apporti leggeri di azoto.');
    if (s.exposition === 'Nord') t.push('Le situazioni adatte al loglio sono miti, soleggiate e presto libere dalla neve.');
    return t;
  }

